//! 两backend共用DAG事实、lease fencing、原run原子链接与重启读回合同。
use agent_core::*;
use agent_storage_ports::*;
use std::sync::Arc;
fn verifier()->Arc<dyn AuthorizationVerifier>{Arc::new(agent_policy::PolicyEngine)}
async fn auth<T:IdentityReadRepository>(s:&T,action:Action,id:&str)->AuthorizationRequest{let i=s.read_identity(&TenantContext::local(),&"local-subject".to_owned().try_into().unwrap()).await.unwrap();AuthorizationRequest{context:agent_identity::local_context(&i,RequestId::String(id.into())).unwrap(),expected_policy:i.policy.version,action,attributes:AuthorizationAttributes{workspace:".".into(),entry_channel:HookChannel::DaemonRpc,tool_effect:None,timestamp_ms:0,network:NetworkBoundary::None}}}
fn node(id:&str,deps:&[&str],kind:WorkflowNodeKind)->WorkflowNodeDefinition{let pure=agent_workflow::is_pure(&kind);WorkflowNodeDefinition{id:id.into(),dependencies:deps.iter().map(|s|(*s).into()).collect(),kind,input:serde_json::json!({"decimal":1.25}),retry:if pure{WorkflowRetryClass::Pure}else{WorkflowRetryClass::Never},max_attempts:1,timeout_ms:60000,compensation:None}}
fn definition()->WorkflowDefinition{WorkflowDefinition{schema_version:1,name:"合同DAG".into(),version:"1.0.0".into(),nodes:vec![node("fork",&[],WorkflowNodeKind::Parallel),node("a",&["fork"],WorkflowNodeKind::AgentRun{message:"原run输入".into()}),node("b",&["fork"],WorkflowNodeKind::WaitUntil{timestamp_ms:0}),node("join",&["a","b"],WorkflowNodeKind::Join)]}}
async fn contract<T:WorkflowRepository+IdentityReadRepository+SessionLifecycleRepository+RunExecutionRepository+RunFactRepository>(s:&T){let p=WorkflowPublish{operation_id:"publish".into(),definition:definition()};let a=auth(s,Action::AgentConfigure,"publish").await;let frozen=s.publish_workflow(&a,&p,verifier()).await.unwrap();assert_eq!(s.publish_workflow(&a,&p,verifier()).await.unwrap(),frozen);let mut conflict=p.clone();conflict.definition.nodes[1].kind=WorkflowNodeKind::AgentRun{message:"different".into()};assert!(s.publish_workflow(&a,&conflict,verifier()).await.is_err());
 let c=WorkflowStart{operation_id:"start".into(),definition_digest:frozen.digest.clone(),input:serde_json::json!({"value":42})};let a=auth(s,Action::SessionPrompt,"start").await;let i=s.start_workflow(&a,&c,verifier()).await.unwrap();assert_eq!(s.start_workflow(&a,&c,verifier()).await.unwrap(),i);let a=auth(s,Action::SessionPrompt,"claim").await;let claims=s.claim_workflow_nodes(&a,"executor-a",8,verifier()).await.unwrap();assert_eq!(claims.len(),1);let claim=&claims[0];let read=s.read_workflow(&TenantContext::local(),&i.id,0,64).await.unwrap();assert_eq!(read.nodes.iter().find(|n|n.key.node_id=="fork").unwrap().status,WorkflowNodeStatus::Completed);assert!(s.claim_workflow_nodes(&a,"executor-b",8,verifier()).await.unwrap().is_empty());
 let mut bad=claim.lease.clone();bad.epoch+=1;assert!(s.renew_workflow_node(&a,&bad,verifier()).await.is_err());assert!(s.finish_workflow_node(&a,&claim.lease,&WorkflowNodeResult::Completed{output:serde_json::json!({"forged":true}),artifacts:vec![]},verifier()).await.is_err());
 let key=agent_workflow::native_session_key(&claim.lease.key).unwrap();let mut workload=auth(s,Action::SessionPrompt,"bind").await;workload.context.principal=s.read_identity(&TenantContext::local(),&RuntimeIdentity::local_workflow().principal.subject_id).await.unwrap().principal;s.bind_workflow_session(&workload,&claim.lease,&key,verifier()).await.unwrap();let create=auth(s,Action::SessionCreate,"create").await;let life=s.commit_session_authorized(&create,&SessionCommand::Create{key:key.clone()},None,"native-session",verifier()).await.unwrap().lifetime;
 let snapshot:RunSnapshot=serde_json::from_value(serde_json::json!({"workflow":{"key":claim.lease.key,"definition":claim.definition},"entry_channel":"daemon_rpc","tools":[],"cwd":".","permission_mode":"risk","sandbox_requested":"native","sandbox_effective":"native","context_read_only":false,"context_token_budget":4096,"tool_catalog_digest":format!("{:x}",sha2::Sha256::digest(b"[]")),"context_policy_fingerprint":"4096:12:60:85","config_generation":0})).unwrap();use sha2::Digest;
 let admission=RunAdmission{workflow_node:Some(claim.lease.clone()),plan_execution:None,session_key:key,expected_lifetime:Some(life),request_id:RequestId::String(claim.lease.operation_id.clone()),input:agent_workflow::native_input(&claim.definition).unwrap(),mode:AdmissionMode::Queue};let a=auth(s,Action::SessionPrompt,&claim.lease.operation_id).await;
 let (_,owner)=s.admit_run_authorized(&admission,&snapshot,&a,verifier()).await.unwrap();let linked=s.read_workflow(&TenantContext::local(),&i.id,0,64).await.unwrap();assert_eq!(linked.nodes.iter().find(|n|n.key==claim.lease.key).unwrap().native_run_id,Some(owner.run_id.clone()));let env=EnterpriseOwnerEnvelope{scope:TenantContext::local(),owner};assert!(s.start_queued_run(&env).await.unwrap());s.commit_run_turn(&env,&TurnCommit{owner:env.owner.clone(),status:RunStatus::Completed,content:Some("原run结果".into()),error:None}).await.unwrap();
 let a=auth(s,Action::SessionPrompt,"finish").await;let result=WorkflowNodeResult::Completed{output:agent_workflow::native_output("原run结果").unwrap(),artifacts:vec![]};s.finish_workflow_node(&a,&claim.lease,&result,verifier()).await.unwrap();assert!(s.finish_workflow_node(&a,&bad,&result,verifier()).await.is_err());assert!(s.claim_workflow_nodes(&a,"executor-a",8,verifier()).await.unwrap().is_empty());let read=s.read_workflow(&TenantContext::local(),&i.id,0,64).await.unwrap();assert_eq!(read.instance.status,WorkflowStatus::Completed);assert!(read.events.iter().any(|e|e.kind=="native_admitted"));assert_eq!(read.instance.task_id,i.id);let foreign=TenantContext{tenant_id:"foreign".to_owned().try_into().unwrap(),..TenantContext::local()};assert!(s.read_workflow(&foreign,&i.id,0,64).await.is_err());
}
#[tokio::test]async fn sqlite_workflow_native_fence(){let root=std::env::temp_dir().join(format!("workflow-contract-{}",std::process::id()));std::fs::create_dir_all(&root).unwrap();let store=agent_storage::RunStore::open(&root.join("facts.sqlite3")).unwrap();contract(&store).await;drop(store);let reopened=agent_storage::RunStore::open(&root.join("facts.sqlite3")).unwrap();let id=format!("wf-{}",agent_workflow::digest(&serde_json::json!([TenantContext::local(),"local-subject","start"])).unwrap());assert_eq!(reopened.read_workflow(&TenantContext::local(),&id,0,64).await.unwrap().instance.status,WorkflowStatus::Completed);drop(reopened);std::fs::remove_dir_all(root).unwrap();}
#[tokio::test]#[ignore="显式自有PG测试库"]async fn postgres_workflow_native_fence(){let database=std::env::var("AGENT_RESOURCE_TEST_DB").unwrap();let user=std::env::var("AGENT_RESOURCE_TEST_USER").unwrap();let schema=format!("workflow_contract_{}",std::process::id());let store=agent_storage_postgres::PgCanonicalStore::connect_local(&database,&user,&schema).await.unwrap();store.provision_initial_domain(&TenantContext::local(),&RuntimeIdentity::local().principal,&[EnterpriseRole::TenantAdmin],&PolicyDocument::local()).await.unwrap();contract(&store).await;store.close().await;assert!(std::process::Command::new("psql").args(["-X","-w","-h","/tmp","-U",&user,"-d",&database,"-c",&format!("DROP SCHEMA {schema} CASCADE")]).stdout(std::process::Stdio::null()).stderr(std::process::Stdio::null()).status().unwrap().success());}
